 "content": "def transform(grid):
    """Bridge gaps along repeated horizontal/vertical marker lines."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = [value for value in counts if value != background]
    if len(foreground) != 1:
        raise ValueError("Expected one foreground color")
    marker = foreground[0]
    out = [row[:] for row in grid]
    occupied = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    if not occupied:
        return out
    min_r = min(r for r, _ in occupied)
    max_r = max(r for r, _ in occupied)
    min_c = min(c for _, c in occupied)
    max_c = max(c for _, c in occupied)

    # Repeated strokes are completed between their extreme marker cells.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 3:
            for c in range(cols[0], cols[-1] + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 3:
            for r in range(rows[0], rows[-1] + 1):
                if out[r][c] == background:
                    out[r][c] = 2

    # Complete the extreme horizontal boundary even when it has only two
    # visible pieces; the side strokes define its full extent.
    for r in (min_r, max_r):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min_c, max_c + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out

